contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough balance for deposit");

        // Deposit into c: this is a state-changing call, so it is its own top-level statement.
        (bool depositSuccess, ) = address(c).call{value: depositAmount}("");
        require(depositSuccess, "deposit failed");

        uint256 balBefore = c.balances(address(this));
        uint256 ethBefore = address(c).balance;

        // Withdraw: state-changing call must be its own top-level statement.
        c.withdraw();

        uint256 balAfter = c.balances(address(this));
        uint256 ethAfter = address(c).balance;

        // General rule: after a successful withdraw, the sender's recorded balance is zero
        // and c's Ether balance decreased by exactly the previous recorded balance.
        assert(balBefore > 0 && balAfter == 0 && ethAfter == ethBefore - balBefore);
    }

    receive() external payable {}
}

